// Concatena intro + slides(+audio) + outro via montagem service
// Input: { production_id, intro_url, slide_urls[], outro_url,
//          intro_audio_url?, outro_audio_url?, scene_audio_urls?[] }
// Output: { production_id, final_path, final_url }

const http = require('http');

const MONTAGEM_HOST = 'montagem';
const MONTAGEM_PORT = 3000;

const body      = $input.first().json.body || $input.first().json;
const pid       = body.production_id;
const introUrl  = body.intro_url;
const slideUrls = body.slide_urls || [];
const outroUrl  = body.outro_url;

// Optional TTS audio
const introAudioUrl    = body.intro_audio_url || null;
const outroAudioUrl    = body.outro_audio_url || null;
const sceneAudioUrls   = body.scene_audio_urls || [];

const clips = [introUrl, ...slideUrls, outroUrl].filter(Boolean);
if (clips.length < 2) throw new Error('precisa de pelo menos intro + 1 slide');

console.log(`[${pid}] Montando ${clips.length} clips, audio_overlay=${sceneAudioUrls.length > 0}`);

function httpPost(host, port, path, payload) {
  return new Promise((resolve, reject) => {
    const data = JSON.stringify(payload);
    const options = {
      hostname: host, port, path, method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(data) }
    };
    const req = http.request(options, res => {
      let body = '';
      res.on('data', c => body += c);
      res.on('end', () => { try { resolve(JSON.parse(body)); } catch(e) { resolve({ raw: body }); } });
    });
    req.on('error', reject);
    req.write(data);
    req.end();
  });
}

// Build segments: each clip optionally paired with audio
const segments = [];

// intro (mute avatar if audio provided)
segments.push({
  video: introUrl,
  audio: introAudioUrl || null,
  mute_video: !!introAudioUrl
});

// slides with scene audio overlay
for (let i = 0; i < slideUrls.length; i++) {
  segments.push({
    video: slideUrls[i],
    audio: sceneAudioUrls[i] || null,
    mute_video: false  // slides have no audio
  });
}

// outro (mute avatar if audio provided)
segments.push({
  video: outroUrl,
  audio: outroAudioUrl || null,
  mute_video: !!outroAudioUrl
});

const r = await httpPost(MONTAGEM_HOST, MONTAGEM_PORT, '/concat', {
  segments,
  // Legacy fallback: also send clips for simple concat if segments not supported
  clips,
  output_key: `${pid}/final.mp4`,
  output_bucket: 'cirlene-video',
});

if (r.error) throw new Error('montagem failed: ' + r.error);
console.log(`[${pid}] Montagem done: ${r.path}`);

return [{ json: { production_id: pid, final_path: r.path, final_url: r.url } }];
